/* Store tools: compatible with existing recipes and offline Android assets. */
(()=>{
const original={openForm,submitForm,rowIngredient,showDetail,render,renderBrew,startBrew};
let photo='',selection={},wake=null,audio=null,deadline=0;
const number=v=>Math.max(0,Number(v)||0);
const toolbar=document.createElement('div');toolbar.className='tools-row';toolbar.innerHTML='<button id="backupOpen" class="outline-button">สำรอง / นำเข้าสูตร</button><span>เวอร์ชัน 1.2</span>';
$('#recipesPage').append(toolbar);
const backup=document.createElement('dialog');backup.className='sheet';backup.id='backupDialog';backup.innerHTML='<header class="sheet-head"><button class="text-button" id="backupClose">ปิด</button><h2>สำรองสูตร</h2></header><div class="sheet-body"><p>ส่งออกสูตรทั้งหมดพร้อมรูป หรือวางข้อมูลสำรองเพื่อนำเข้า สูตรเดิมจะยังอยู่</p><button id="backupDownload" class="outline-button">ดาวน์โหลดไฟล์ JSON</button><label>ข้อมูลสำรอง<textarea id="backupText" rows="8" aria-label="ข้อมูลสำรอง"></textarea></label><button id="backupCopy" class="outline-button">คัดลอกข้อมูลสำรอง</button><label>เลือกไฟล์สำรอง<input id="backupFile" type="file" accept=".json,application/json"></label><button id="backupImport" class="outline-button">นำเข้าข้อมูลในช่องด้านบน</button><p id="backupMessage" role="status"></p></div>';document.body.append(backup);
const extra=document.createElement('section');extra.id='extraFields';extra.innerHTML='<h3>รูปเมนูและเมล็ดกาแฟ</h3><label>รูปเมนู<input type="file" id="photoFile" accept="image/jpeg,image/png,image/webp"><img id="photoPreview" alt="รูปเมนู" hidden></label><button type="button" id="photoRemove" class="text-button">ลบรูป</button><div class="form-grid"><label>ชื่อเมล็ด / แหล่งปลูก<input id="beanName"></label><label>ระดับคั่ว<input id="roast" placeholder="เช่น คั่วกลาง"></label><label>เบอร์บด<input id="grind"></label><label>อุณหภูมิน้ำ (°C)<input id="temperature" type="number" min="0" max="100"></label></div><h3>ขนาดแก้วและความหวาน</h3><p class="help">เพิ่มสูตรแยกตามตัวเลือก ปริมาณเป็นค่าที่คุณกำหนดเอง เช่น ชื่อวัตถุดิบ นม ปริมาณ 135 และหน่วย ml</p><div id="variantRows"></div><button type="button" class="outline-button" id="variantAdd">＋ เพิ่มตัวเลือกขนาด / ความหวาน</button><h3>ต้นทุนบรรจุภัณฑ์</h3><label>แก้ว ฝา หลอด รวมต่อแก้ว (บาท)<input id="packaging" type="number" min="0" step="0.01"></label><p class="help">ในวัตถุดิบ ใส่ราคาแพ็กและปริมาณต่อแพ็กในหน่วยเดียวกับที่ใช้ เช่น นม 135 ml ราคา 50 บาทต่อ 1,000 ml หากกรอกราคาวัตถุดิบครบ ระบบจะคำนวณต้นทุนแทนช่องต้นทุนรวม</p>';
$('#deleteRecipe').before(extra);
function variantRow(v={}){const d=document.createElement('div');d.className='variant-row';d.innerHTML=`<div class="form-grid"><label>ชื่อตัวเลือก<input class="variant-label" value="${esc(v.label||'')}" placeholder="16 oz · หวานน้อย"></label><label>ขนาดแก้ว<input class="variant-size" value="${esc(v.size||'')}"></label></div><label>วัตถุดิบของตัวเลือกนี้ (หนึ่งรายการต่อบรรทัด)<textarea class="variant-lines" rows="3" placeholder="นม | 135 | ml&#10;ไซรัป | 5 | ml">${esc((v.ingredients||[]).map(i=>`${i.name} | ${i.qty} | ${i.unit}`).join('\n'))}</textarea></label><button type="button" class="remove-variant text-button">ลบตัวเลือก</button>`;return d}
rowIngredient=function(v={}){const d=original.rowIngredient(v);d.className='ingredient-editor';d.innerHTML=`<div class="ingredient-row"><input class="ing-name" aria-label="ชื่อวัตถุดิบ" placeholder="วัตถุดิบ" value="${esc(v.name||'')}"><input class="ing-amount" aria-label="ปริมาณพร้อมหน่วย" placeholder="135 ml" value="${esc(v.amount||'')}"><button type="button" class="remove-ingredient remove-row">×</button></div><div class="form-grid"><label>ราคาแพ็ก (บาท)<input class="pack-price" type="number" min="0" step="0.01" value="${v.packPrice??''}"></label><label>ปริมาณต่อแพ็ก<input class="pack-qty" type="number" min="0" step="0.01" value="${v.packQty??''}" placeholder="หน่วยเดียวกับที่ใช้"></label></div>`;d.querySelector('.remove-ingredient').addEventListener('click',e=>{e.stopPropagation();d.remove()});return d};
openForm=function(id){original.openForm(id);const r=recipes.find(x=>x.id===id)||{};photo=r.photo||'';$('#photoFile').value='';previewPhoto();for(const k of ['beanName','roast','grind','temperature','packaging'])$('#'+k).value=r[k]??'';$('#variantRows').innerHTML='';(r.variants||[]).forEach(v=>$('#variantRows').append(variantRow(v)))};
const cropAgain=document.createElement('button');cropAgain.type='button';cropAgain.id='photoCropAgain';cropAgain.className='outline-button';cropAgain.textContent='จัดกรอบรูป';$('#photoRemove').before(cropAgain);
cropAgain.onclick=async()=>{if(!photo)return;try{const cropped=await CoffeeCrop(photo);if(cropped){photo=cropped;previewPhoto()}}catch(e){toast(e.message)}};
function previewPhoto(){$('#photoPreview').hidden=!photo;$('#photoPreview').src=photo;cropAgain.hidden=!photo;$('#photoRemove').hidden=!photo}
const priorSave=save;
save=function(){try{priorSave()}catch(e){toast('พื้นที่เก็บเต็ม กรุณาลดรูปหรือสำรองสูตรก่อน');throw e}};
submitForm=function(){const id=$('#recipeId').value;const old=recipes.map(r=>({...r}));const ingredients=$$('#ingredientRows .ingredient-editor').map(d=>({name:d.querySelector('.ing-name').value.trim(),amount:d.querySelector('.ing-amount').value.trim(),packPrice:d.querySelector('.pack-price').value===''?null:number(d.querySelector('.pack-price').value),packQty:number(d.querySelector('.pack-qty').value)})).filter(i=>i.name);const variants=$$('#variantRows .variant-row').map(d=>({label:d.querySelector('.variant-label').value.trim(),size:d.querySelector('.variant-size').value.trim(),ingredients:d.querySelector('.variant-lines').value.split('\n').filter(x=>x.trim()).map(line=>{const [name,qty,unit]=line.split('|').map(x=>x.trim());if(!name||!qty||!Number.isFinite(Number(qty))||Number(qty)<0||!unit)throw Error('ตัวเลือกสูตรต้องเป็น ชื่อ | ปริมาณ | หน่วย');return{name,qty:Number(qty),unit}})})).filter(v=>v.label);try{original.submitForm();const r=recipes.find(r=>r.id===id)||recipes[0];r.ingredients=ingredients;r.variants=variants;r.photo=photo;for(const k of ['beanName','roast','grind','temperature'])r[k]=$('#'+k).value.trim();r.packaging=number($('#packaging').value);r.costMode=ingredients.length&&ingredients.every(i=>i.packPrice!==null&&i.packQty>0&&Number.isFinite(parseFloat(i.amount)))?'ingredients':'manual';if(r.costMode==='ingredients')r.cost=costOf(r,r.ingredients);save();render()}catch(e){recipes=old;save();render();throw e}};
function costOf(r,items){return number(r.packaging)+items.reduce((sum,i)=>{const source=r.ingredients.find(x=>x.name===i.name);return sum+(source?.packQty>0?number(i.qty??parseFloat(i.amount))*number(source.packPrice)/source.packQty:0)},0)}
render=function(){original.render();$$('.recipe-card').forEach(el=>{const r=recipes.find(r=>r.id===el.dataset.id);if(r?.photo){const span=el.querySelector('.recipe-icon');span.innerHTML=`<img src="${esc(r.photo)}" alt="">`;span.classList.add('has-photo')}})};
showDetail=function(id){selection={};original.showDetail(id);const r=current;if(r.photo)$('#detailContent .detail-icon').innerHTML=`<img class="hero-photo" src="${esc(r.photo)}" alt="${esc(r.name)}">`;const body=$('#detailContent .detail-body');if(r.beanName||r.grind||r.roast||r.temperature)body.insertAdjacentHTML('beforeend',`<h3>เมล็ดกาแฟและการตั้งค่า</h3><p>${[r.beanName,r.roast,r.grind&&`เบอร์บด ${r.grind}`,r.temperature&&`${r.temperature}°C`].filter(Boolean).map(esc).join(' · ')}</p>`);body.insertAdjacentHTML('beforeend','<button class="outline-button" id="duplicateRecipe">คัดลอกสูตรนี้</button>');if(r.variants?.length){const block=document.createElement('label');block.className='variant-select';block.innerHTML=`ขนาด / ความหวาน<select id="variantSelect"><option value="">สูตรหลัก · ${esc(r.size)}</option>${r.variants.map((v,i)=>`<option value="${i}">${esc(v.label)}</option>`).join('')}</select>`;body.prepend(block);$('#variantSelect').addEventListener('change',()=>{const value=$('#variantSelect').value;selection=value===''?{}:r.variants[Number(value)];body.querySelector('.ingredients').innerHTML=(selection.ingredients||r.ingredients).map(i=>`<li><span>${esc(i.name)}</span><strong>${esc(i.amount??`${i.qty} ${i.unit}`)}</strong></li>`).join('');$('#detailContent .detail-hero p').textContent=`${r.serve} · ${selection.size||r.size} · ${selection.label||'สูตรหลัก'}`})}};
async function acquireWake(){if(!$('#brewDialog').open||!('wakeLock' in navigator))return;try{wake=await navigator.wakeLock.request('screen')}catch{toast('เครื่องนี้ไม่อนุญาตล็อกหน้าจอ โปรดตั้งเวลาพักหน้าจอเอง')}}
function releaseWake(){wake?.release().catch(()=>{});wake=null}
function unlockAudio(){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume()}catch{}}
function beep(){if(audio){[0,.25,.5].forEach(delay=>{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=880;g.gain.value=.15;o.connect(g);g.connect(audio.destination);o.start(audio.currentTime+delay);o.stop(audio.currentTime+delay+.15)})}navigator.vibrate?.([150,100,150])}
startBrew=function(id){unlockAudio();original.startBrew(id);if($('#brewDialog').open){if(selection.label){brew.recipe=structuredClone(brew.recipe);const all=(selection.ingredients||[]).map(i=>`${i.name} ${i.qty} ${i.unit}`).join(' · ');brew.recipe.steps.unshift({text:`เตรียม ${selection.label}: ${all}`,time:0});renderBrew()}acquireWake()}};
renderBrew=function(){original.renderBrew();$('#brewDialog').classList.add('bar-mode');const p=document.createElement('p');p.className='help';p.textContent='โหมดหลังบาร์ · พยายามเปิดหน้าจอค้างระหว่างชง';$('#brewContent .brew-main').append(p)};
startTimer=function(){unlockAudio();const b=$('[data-start-timer]');b.disabled=true;b.textContent='กำลังจับเวลา';deadline=Date.now()+brew.remaining*1000;clearInterval(brew.timer);brew.timer=setInterval(()=>{brew.remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('#timer').textContent=formatTime(brew.remaining);if(!brew.remaining){clearInterval(brew.timer);b.textContent='✓ ครบเวลาแล้ว';beep();toast('ครบเวลาแล้ว')}},250)};
$('#brewDialog').addEventListener('close',()=>{clearInterval(brew.timer);releaseWake();selection={}});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&$('#brewDialog').open)acquireWake()});
function validateBackup(data){const list=Array.isArray(data)?data:data.recipes;if(!Array.isArray(list)||list.length>500)throw Error('ไฟล์สำรองไม่ถูกต้อง');return list.map(r=>{if(!r||typeof r.name!=='string'||!r.name.trim()||!Array.isArray(r.ingredients)||!Array.isArray(r.steps))throw Error('ข้อมูลสูตรไม่ครบ');if(r.photo&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(r.photo))throw Error('รูปในไฟล์ไม่ถูกต้อง');return{...r,id:crypto.randomUUID(),name:r.name.slice(0,200),price:number(r.price),cost:number(r.cost),ingredients:r.ingredients.map(i=>({name:String(i.name||''),amount:String(i.amount||''),packPrice:i.packPrice==null?null:number(i.packPrice),packQty:number(i.packQty)})),steps:r.steps.map(s=>({text:String(s.text||''),time:number(s.time)})),variants:Array.isArray(r.variants)?r.variants.map(v=>({label:String(v.label||''),size:String(v.size||''),ingredients:Array.isArray(v.ingredients)?v.ingredients.map(i=>({name:String(i.name||''),qty:number(i.qty),unit:String(i.unit||'')})):[]})):[]}})}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.id==='backupOpen'){$('#backupText').value=JSON.stringify({version:1,recipes},null,2);$('#backupMessage').textContent='';backup.showModal()}if(b.id==='backupClose')backup.close();if(b.id==='backupDownload'){const blob=new Blob([JSON.stringify({version:1,recipes},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='coffee-recipes-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);$('#backupMessage').textContent='หากแอปไม่รองรับดาวน์โหลด ให้คัดลอกข้อมูลสำรองไปเก็บไว้แทน'}if(b.id==='backupCopy'){await navigator.clipboard.writeText($('#backupText').value);toast('คัดลอกแล้ว')}if(b.id==='backupImport'){const text=$('#backupText').value;if(text.length>12000000)throw Error('ไฟล์ใหญ่เกิน 12 MB');const additions=validateBackup(JSON.parse(text));const old=recipes;recipes=[...recipes,...additions];try{save()}catch(e){recipes=old;throw e}render();$('#backupMessage').textContent=`นำเข้าสำเร็จ ${additions.length} สูตร โดยเก็บสูตรเดิมไว้`}if(b.id==='variantAdd')$('#variantRows').append(variantRow());if(b.classList.contains('remove-variant'))b.parentElement.remove();if(b.id==='photoRemove'){photo='';previewPhoto()}if(b.id==='duplicateRecipe'){const copy=structuredClone(current);copy.id=crypto.randomUUID();copy.name+=' (สำเนา)';recipes.unshift(copy);save();render();$('#detailDialog').close();openForm(copy.id)}}catch(err){toast(err.message||'ดำเนินการไม่สำเร็จ')}});
$('#backupFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>12000000)return toast('ไฟล์ใหญ่เกิน 12 MB');$('#backupText').value=await f.text()});
$('#photoFile').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(!/^image\/(jpeg|png|webp)$/.test(f.type)||f.size>15000000)throw Error('เลือกรูป JPG, PNG หรือ WebP ไม่เกิน 15 MB');const cropped=await CoffeeCrop(f);if(cropped){photo=cropped;previewPhoto()}}catch(err){toast(err.message||'อ่านรูปไม่ได้ กรุณาเลือกรูปอื่น')}finally{e.target.value=''}});
// Capture form errors before the original submit handler closes the editor.
$('#recipeForm').addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();if(!$('#name').value.trim())return;try{submitForm();$('#recipeDialog').close()}catch(err){toast(err.message||'บันทึกไม่สำเร็จ')}},true);
render();
})();
